-- ==========================================================================
-- MERCADO DIRECTO - DATOS UNIFICADOS (VERSIÓN CORREGIDA)
-- Ejecutar DESPUÉS de crear las tablas (script 3) y ANTES de crear índices.
-- Filas: departamento 25, provincia 32, distrito 40, agricultor 2400, ubicacion_agricultor 3120, categoria 10, producto 50, oferta_cosecha 42000, cliente_consumidor 24000, direccion_cliente 33600, pedido 85200, detalle_pedido 170012, pedido_agrupado 1721, detalle_pedido_agrupado 6107
-- ==========================================================================

BEGIN;

-- DEPARTAMENTO (25 registros)

-- PROVINCIA (32 registros)

-- DISTRITO (40 registros)

-- AGRICULTOR (2400 registros)

-- UBICACION_AGRICULTOR (3120 registros)

-- CATEGORIA (10 registros)

-- PRODUCTO (50 registros)

-- OFERTA_COSECHA (42000 registros)

-- CLIENTE_CONSUMIDOR (24000 registros)

-- DIRECCION_CLIENTE (33600 registros)

-- PEDIDO (85200 registros)

-- DETALLE_PEDIDO (170012 registros)

-- PEDIDO_AGRUPADO (1721 registros)

-- DETALLE_PEDIDO_AGRUPADO (6107 registros)

-- ==========================================================================
-- Ajuste de secuencias (siguiente id = máximo + 1)
-- ==========================================================================
DO $$
BEGIN
    PERFORM setval(pg_get_serial_sequence('mercado.departamento', 'departamento_id'), (SELECT max(departamento_id) FROM mercado.departamento));
    PERFORM setval(pg_get_serial_sequence('mercado.provincia', 'provincia_id'), (SELECT max(provincia_id) FROM mercado.provincia));
    PERFORM setval(pg_get_serial_sequence('mercado.distrito', 'distrito_id'), (SELECT max(distrito_id) FROM mercado.distrito));
    PERFORM setval(pg_get_serial_sequence('mercado.agricultor', 'agricultor_id'), (SELECT max(agricultor_id) FROM mercado.agricultor));
    PERFORM setval(pg_get_serial_sequence('mercado.ubicacion_agricultor', 'ubicacion_agricultor_id'), (SELECT max(ubicacion_agricultor_id) FROM mercado.ubicacion_agricultor));
    PERFORM setval(pg_get_serial_sequence('mercado.categoria', 'categoria_id'), (SELECT max(categoria_id) FROM mercado.categoria));
    PERFORM setval(pg_get_serial_sequence('mercado.producto', 'producto_id'), (SELECT max(producto_id) FROM mercado.producto));
    PERFORM setval(pg_get_serial_sequence('mercado.oferta_cosecha', 'oferta_id'), (SELECT max(oferta_id) FROM mercado.oferta_cosecha));
    PERFORM setval(pg_get_serial_sequence('mercado.cliente_consumidor', 'cliente_id'), (SELECT max(cliente_id) FROM mercado.cliente_consumidor));
    PERFORM setval(pg_get_serial_sequence('mercado.direccion_cliente', 'direccion_id'), (SELECT max(direccion_id) FROM mercado.direccion_cliente));
    PERFORM setval(pg_get_serial_sequence('mercado.pedido', 'pedido_id'), (SELECT max(pedido_id) FROM mercado.pedido));
    PERFORM setval(pg_get_serial_sequence('mercado.detalle_pedido', 'detalle_pedido_id'), (SELECT max(detalle_pedido_id) FROM mercado.detalle_pedido));
    PERFORM setval(pg_get_serial_sequence('mercado.pedido_agrupado', 'pedido_agrupado_id'), (SELECT max(pedido_agrupado_id) FROM mercado.pedido_agrupado));
    PERFORM setval(pg_get_serial_sequence('mercado.detalle_pedido_agrupado', 'detalle_pedido_agrupado_id'), (SELECT max(detalle_pedido_agrupado_id) FROM mercado.detalle_pedido_agrupado));
END $$;

COMMIT;